from decimal import Decimal


def _value(record: dict, field: str):
    value = record.get(field, "")
    return "" if value is None else value


def _old_value(old: dict | None, field: str):
    if not old:
        return ""
    value = old.get(field, "")
    return "" if value is None else value


def _text(value) -> str:
    return "" if value is None else str(value)


def _number(value) -> Decimal:
    if value is None or value == "":
        return Decimal("0")
    return Decimal(str(value))


def _date_equal(left, right) -> bool:
    return _text(left) == _text(right)


def _date_gte(left, right) -> bool:
    left_text = _text(left)
    right_text = _text(right)
    if left_text == "00000000" or right_text == "00000000":
        return False
    return left_text >= right_text


def _failure(code: str, message: str, severity: str = "BLOCK") -> dict:
    return {
        "code": code,
        "message": message,
        "severity": severity,
    }


def validate(
    record: dict,
    old: dict | None = None,
    event: str = "INSERT",
    today: str = "20260901",
) -> list[dict]:
    errors: list[dict] = []

    amount = _value(record, "AMT")
    status = _text(_value(record, "STAT_CD"))
    lost_reason = _text(_value(record, "LOST_RSN"))
    close_date = _value(record, "CLOSE_DT")
    stage_pct = _value(record, "STAGE_PCT")

    # OPP-001
    if event in ("INSERT", "UPDATE"):
        if _number(amount) < Decimal("0"):
            errors.append(_failure("E3001", "Amount negative"))

    # OPP-002
    if event in ("INSERT", "UPDATE"):
        if status == "W" and _number(amount) == Decimal("0"):
            errors.append(_failure("E3002", "Won opportunity requires amount"))

    # OPP-003
    if event in ("INSERT", "UPDATE"):
        if status == "L" and lost_reason == "":
            errors.append(_failure("E3003", "Lost reason required"))

    # OPP-004
    if event in ("INSERT", "UPDATE"):
        if status == "W" and _date_equal(close_date, "00000000"):
            errors.append(_failure("E3004", "Won opportunity requires close date"))

    # OPP-005
    if event == "UPDATE":
        old_status = _text(_old_value(old, "STAT_CD"))
        if old_status == "W" and status != "W":
            errors.append(_failure("E3005", "Cannot reopen a won opportunity"))

    # OPP-006
    if event in ("INSERT", "UPDATE"):
        stage = _number(stage_pct)
        consistent = (
            (status == "P" and stage == Decimal("10"))
            or (status == "Q" and stage == Decimal("25"))
            or (status == "N" and stage == Decimal("60"))
            or (status == "W" and stage == Decimal("100"))
            or (status == "L" and stage == Decimal("0"))
        )
        if not consistent:
            errors.append(
                _failure("E3006", "Stage percent inconsistent with status")
            )

    # OPP-007
    if event == "INSERT":
        if not (
            _date_equal(close_date, "00000000")
            or _date_gte(close_date, today)
        ):
            errors.append(
                _failure("E3007", "Close date in past", "WARN")
            )

    return errors


def is_blocked(errors: list[dict]) -> bool:
    return any(error.get("severity") == "BLOCK" for error in errors)
